import{_ as r,c as o,o as n,a0 as s}from"./chunks/framework.DE5X-pmd.js";const d=JSON.parse('{"title":"什么是 C++","description":"","frontmatter":{},"headers":[],"relativePath":"cpp_course/index.md","filePath":"cpp_course/index.md"}'),e={name:"cpp_course/index.md"};function i(a,t,l,c,p,_){return n(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="什么是-c" tabindex="-1">什么是 C++ <a class="header-anchor" href="#什么是-c" aria-label="Permalink to &quot;什么是 C++&quot;">​</a></h1><p>C++ 是一种<strong>高性能系统编程语言</strong>，结合了<strong>面向对象、泛型编程和底层控制</strong>的特性。它以<strong>高效和灵活</strong>著称，非常适合对计算机原理、游戏开发和高性能软件感兴趣的学习者。</p><p>C++ 的主要特点包括：</p><ul><li><strong>静态类型语言</strong>：编译时检查类型，提高程序可靠性。</li><li><strong>面向对象</strong>：支持类、对象、继承、多态等概念，便于模块化和复用。</li><li><strong>底层控制</strong>：可以直接操作内存和硬件资源，适合系统级编程。</li><li><strong>高性能</strong>：编译生成的程序执行速度快，适合对性能要求高的应用。</li><li><strong>跨平台</strong>：支持在 Windows、Linux、Mac 等操作系统上开发。</li><li><strong>丰富的标准库</strong>：提供容器、算法、输入输出等多种工具。</li><li><strong>可扩展性</strong>：可以与 C、汇编等语言结合，完成复杂系统开发。</li></ul><p>C++ 由 Bjarne Stroustrup 于 20 世纪 80 年代设计，受 C 语言启发，兼顾效率与抽象能力。它广泛应用于<strong>操作系统、游戏引擎、图形渲染、金融计算等领域</strong>。</p>',5)])])}const u=r(e,[["render",i]]);export{d as __pageData,u as default};
